```tsx
import "./ProblemTable.css";

export interface ProblemRow {
  readonly title: string;
  readonly pattern: string;
  readonly minutes: number;
  readonly review: string;
  readonly due: boolean;
}

export interface ProblemTableProps {
  readonly rows: readonly ProblemRow[];
}

export function ProblemTable({ rows }: ProblemTableProps) {
  return (
    <div
      className="problem-table-wrap"
      role="region"
      aria-label="Solved problems"
      tabIndex={0}
    >
      <table className="problem-table">
        <caption className="sr-only">Solved problems and their next review</caption>
        <thead>
          <tr>
            <th scope="col">Title</th>
            <th scope="col">Pattern</th>
            <th scope="col" className="problem-table__num">Minutes</th>
            <th scope="col">Next review</th>
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 ? (
            <tr>
              <td className="problem-table__empty" colSpan={4}>
                No solved problems yet.
              </td>
            </tr>
          ) : (
            rows.map((row, index) => (
              <tr key={`${row.title}-${index}`}>
                <td>{row.title}</td>
                <td className="problem-table__pattern">{row.pattern}</td>
                <td className="problem-table__num">{row.minutes}</td>
                <td
                  className={
                    row.due
                      ? "problem-table__review problem-table__review--due"
                      : "problem-table__review"
                  }
                >
                  {row.review}
                  {row.due ? <span className="problem-table__tag">Today</span> : null}
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
}
```

