  display: inline-block;
  margin-inline-start: 0.5em;
  padding: 0.1em 0.6em;
  border: 1px solid var(--cresyl);
  border-radius: 999px;
  color: var(--ink);
  font-size: 0.8em;
  font-weight: 600;
  white-space: nowrap;
}

.problem-table__empty {
  color: var(--muted);
  text-align: center;
  padding-block: 1.2em;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
